namespace sv_0d43f8b6c2f643e2a38e3d024d5df5c4.Components;

public enum ScreenSize
{
    Mobile,
    Tablet,
    Desktop
}

let dotNetRef = null;
let resizeHandler = null;

export function initialize(ref) {
